	for _, tc := range []struct {
		name    string
		body    string
		columns int
		remote  []any
		upload  []any
	}{
		{
			name:    "unicode and file numbers",
			body:    "한국어,😀,�,42,true,false\n00123,12345678901234567890,1.5,-2,TRUE,False\n",
			columns: 6,
